sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float amount;
uniform float curve;
uniform float hardCut;
uniform float lumaOnly;
uniform float opacity;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float e = pow(saturate(beat), curve);
    float3 s = unp(c);
    float k = mix(e, step(0.5, e), hardCut) * amount;
    float l = luma(s);
    float3 inv = lumaOnly > 0.5 ? s * ((1.0 - l) / max(l, 0.02)) : 1.0 - s;
    float3 o = mix(s, inv, k);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
